SELECT rule.* FROM bm_operate_rule AS rule JOIN lm_resource_permission bm ON rule.id = bm.resource_id WHERE rule.is_deleted = 0 and bm.dept_id in
#{item}
group by rule.id

SELECT rv.id AS id, rv.version AS version, r.name AS name, r.code AS code FROM bm_operate_rule_version rv INNER JOIN bm_operate_rule r ON r.id = rv.operate_id AND r.is_deleted = 0 WHERE rv.id IN
#{id}
AND rv.is_deleted = 0 ORDER BY rv.id
